const areas = [
  { id: 'frontend', name: 'Frontend security, correctness, and performance', brief: 'Audit SpendX frontend security and reliability', scope: 'Inspect client/src components, views, context, utilities, route setup, and client package scripts. Review XSS/HTML rendering, token and sensitive-data handling, client-side authorization assumptions, input validation, network error/race handling, broken routes, runtime crashes, accessibility-related risks, and avoidable performance bottlenecks. Do not change files.' },
  { id: 'auth-api', name: 'Authentication, authorization, and API routes', brief: 'Audit SpendX authentication and API routes', scope: 'Inspect server/server.js, server/middleware, and core server/routes/API code. Review password/JWT handling, auth bypasses, object-level authorization/IDOR, validation and injection, CSRF/CORS, rate limits, error leakage, API contracts, route stability, and crashes. Do not change files.' },
  { id: 'data-services', name: 'Database, persistence, models, and business services', brief: 'Audit SpendX database and business services', scope: 'Inspect server/models, server/services, database connection/fallback logic, and data files by metadata only (do not read or reveal user records). Review query safety, schema/validation, ownership isolation, inconsistent persistence, race conditions, failure recovery, resource bounds, and data exposure. Do not change files.' },
  { id: 'uploads-integrations', name: 'Uploads, OCR, AI integrations, and outbound requests', brief: 'Audit SpendX uploads and external integrations', scope: 'Inspect upload/OCR/AI integration code in server routes, services, and utilities. Review MIME/extension/content checks, upload limits, temp-file cleanup, path traversal, parser resource exhaustion, SSRF/open redirects, remote request timeouts, API-key handling without revealing values, prompt/data exposure, and exception behavior. Do not change files.' },
  { id: 'dependencies-deploy', name: 'Dependencies, secrets hygiene, CI, and deployment', brief: 'Audit SpendX packages and deployment configuration', scope: 'Inspect root/client/server package manifests and lockfiles, .gitignore, .env.example only (never read .env contents), tracked-file status without printing secret values, CI workflows, Vercel/deployment configuration, and project README. Identify dependency/security-scan gaps, secret exposure risks, unsafe build/start assumptions, missing security headers, environment misconfiguration, and deployment failures. Do not change files.' }
];
const reviewSchema = JSON.stringify({
  type: 'object',
  properties: {
    id: { type: 'string' },
    category: { type: 'string' },
    summary: { type: 'string' },
    findings: { type: 'array', items: { type: 'object', properties: {
      severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low', 'info'] },
      confidence: { type: 'string', enum: ['confirmed', 'potential', 'unverified'] },
      title: { type: 'string' },
      location: { type: 'string' },
      evidence: { type: 'string' },
      impact: { type: 'string' },
      safe_recommendation: { type: 'string' }
    }, required: ['severity', 'confidence', 'title', 'location', 'evidence', 'impact', 'safe_recommendation'] } },
    positive_checks: { type: 'array', items: { type: 'string' } },
    limitations: { type: 'array', items: { type: 'string' } }
  },
  required: ['id', 'category', 'summary', 'findings', 'positive_checks', 'limitations']
});
const mapped = await parallel('Audit SpendX application areas', () => areas.map(area => agent(
  'Audit exactly this SpendX area: ' + area.name + '.\n' + area.scope + '\n' +
  'Project root: C:\\Abhay\\SpendX. This is a read-only code review; do not modify files or run destructive tests. Never read server/.env contents, never print/quote any credentials, and do not access production services or alter databases. Use source evidence and direct, safe local checks only. Separate confirmed code defects from potential risks and unverified runtime/deployment issues. Severity definitions: critical = unauthenticated full compromise or broad sensitive-data loss; high = serious exploitable exposure/privilege escalation; medium = bounded security or reliability impact; low = limited impact; info = hardening note. Avoid duplicate or speculative findings. Return the exact structured fields in the shared schema, with the area id exactly ' + area.id + '.',
  { brief: area.brief, schema: reviewSchema, sandbox: 'shared', effort_level: 'standard' }
)), { schema: reviewSchema });
const successes = mapped.filter(result => result.ok).map(result => result.value);
const failures = mapped.map((result, index) => result.ok ? null : { area: areas[index].id, error: result.error.message }).filter(Boolean);
const reduceSchema = JSON.stringify({
  type: 'object',
  properties: {
    executive_summary: { type: 'string' },
    priority_findings: { type: 'array', items: { type: 'object', properties: {
      severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low', 'info'] },
      confidence: { type: 'string', enum: ['confirmed', 'potential', 'unverified'] },
      title: { type: 'string' },
      location: { type: 'string' },
      evidence: { type: 'string' },
      impact: { type: 'string' },
      safe_recommendation: { type: 'string' }
    }, required: ['severity', 'confidence', 'title', 'location', 'evidence', 'impact', 'safe_recommendation'] } },
    cross_cutting_gaps: { type: 'array', items: { type: 'string' } },
    audit_limitations: { type: 'array', items: { type: 'string' } }
  },
  required: ['executive_summary', 'priority_findings', 'cross_cutting_gaps', 'audit_limitations']
});
const synthesis = await agent(
  'Synthesize these five independent read-only SpendX audit results. Deduplicate overlapping items; preserve severity and confirmed/potential/unverified status; do not promote speculative claims. Sort confirmed findings by severity first. Include key cross-cutting testing or deployment gaps and limitations. Do not claim fixes or tests that have not happened. Findings: ' + JSON.stringify(successes) + ' Review failures: ' + JSON.stringify(failures),
  { brief: 'Synthesize SpendX audit findings', schema: reduceSchema, sandbox: 'shared', effort_level: 'standard' }
);
return { reviews: successes, failures, synthesis: synthesis.ok ? synthesis.value : null, synthesis_error: synthesis.ok ? null : synthesis.error.message };

